function validate([nums, queries]) {
  if (!Array.isArray(nums) || nums.length < 2 || nums.length > 100000) return 'nums needs at least 2 values.';
  if (nums.some(v => !Number.isInteger(v) || v < 1 || v > 100)) return 'Each value in nums is an integer from 1 to 100.';
  if (!Array.isArray(queries) || queries.length < 1 || queries.length > 20000) return 'queries needs 1 to 20000 pairs.';
  for (const query of queries) {
    if (!Array.isArray(query) || query.length !== 2) return 'Each query is a pair [l, r].';
    const [l, r] = query;
    if (!Number.isInteger(l) || !Number.isInteger(r) || l < 0 || l >= r || r >= nums.length) return 'Each query needs 0 <= l < r < nums.length.';
  }
  return null;
}

