function minDifference(nums, queries) {
  const MAX = 100;
  const prefix = [new Array(MAX + 1).fill(0)];
  for (let i = 0; i < nums.length; i++) {
    const row = prefix[i].slice();
    row[nums[i]]++;
    prefix.push(row);
  }
  const answer = [];
  for (const [left, right] of queries) {
    let previous = -1;
    let best = Infinity;
    for (let value = 1; value <= MAX; value++) {
      if (prefix[right + 1][value] - prefix[left][value] > 0) {
        if (previous !== -1) {
          best = Math.min(best, value - previous);
        }
        previous = value;
      }
    }
    answer.push(best === Infinity ? -1 : best);
  }
  return answer;
}

