function minDifference(nums, queries) {
  return queries.map(([l, r]) => {
    let gap = -1;
    for (let a = l; a <= r; a++)
      for (let b = a + 1; b <= r; b++) {
        const d = Math.abs(nums[a] - nums[b]);
        if (d !== 0 && (gap === -1 || d < gap)) gap = d;
      }
    return gap;
  });
}

