function generate(rand, size) {
  const large = size === 'large';
  const n = large ? 2000 : 2 + Math.floor(rand() * 7);
  // Sometimes only a few distinct values, in runs, so many slices hold one repeated value.
  const low = 1 + Math.floor(rand() * 100);
  const high = Math.min(100, low + (rand() < 0.4 ? Math.floor(rand() * 4) : Math.floor(rand() * 100)));
  const nums = [];
  while (nums.length < n) {
    const value = low + Math.floor(rand() * (high - low + 1));
    const run = rand() < 0.3 ? 1 + Math.floor(rand() * (large ? 40 : 3)) : 1;
    for (let k = 0; k < run && nums.length < n; k++) nums.push(value);
  }
  const q = large ? 2000 : 1 + Math.floor(rand() * 6);
  const queries = [];
  for (let k = 0; k < q; k++) {
    const left = Math.floor(rand() * (n - 1));
    const span = rand() < 0.5 ? 1 + Math.floor(rand() * Math.min(5, n - 1 - left)) : 1 + Math.floor(rand() * (n - 1 - left));
    queries.push([left, left + span]);
  }
  return [nums, queries];
}
